def w(path, content):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    open(path, "w").write(content)
    print(f"  wrote {path}")

w("backend/app/api/__init__.py", "def register_blueprints(app):\n    from .auth import auth_bp\n    from .health import health_bp\n    from .users import users_bp\n    from .schedule import schedule_bp\n    from .upload import upload_bp\n    app.register_blueprint(auth_bp)\n    app.register_blueprint(health_bp)\n    app.register_blueprint(users_bp)\n    app.register_blueprint(schedule_bp)\n    app.register_blueprint(upload_bp)\n")

w("backend/config.py", "import os\nbasedir = os.path.abspath(os.path.dirname(__file__))\n\ndef build_database_url():\n    url = os.environ.get('DATABASE_URL', '')\n    if url: return url\n    host = os.environ.get('DB_HOST', '')\n    user = os.environ.get('DB_USER', '')\n    password = os.environ.get('DB_PASSWORD', '')\n    port = os.environ.get('DB_PORT', '3306')\n    name = os.environ.get('DB_NAME', '')\n    if host and user and name and password:\n        return f'mysql+pymysql://{user}:{password}@{host}:{port}/{name}?charset=utf8mb4'\n    return f'sqlite:///{os.path.join(basedir, \"dev.db\")}'\n\n_db_url = build_database_url()\n\nclass Config:\n    SECRET_KEY = os.environ.get('SECRET_KEY', 'dev-secret-change-me')\n    JWT_SECRET_KEY = os.environ.get('JWT_SECRET_KEY', 'jwt-secret-change-me')\n    SQLALCHEMY_DATABASE_URI = _db_url\n    SQLALCHEMY_TRACK_MODIFICATIONS = False\n    JSON_AS_ASCII = False\n    UPLOAD_FOLDER = os.path.join(basedir, 'uploads')\n    SQLALCHEMY_ENGINE_OPTIONS = (\n        {'connect_args': {'check_same_thread': False}}\n        if 'sqlite' in _db_url\n        else {'pool_pre_ping': True, 'pool_recycle': 3600}\n    )\n")

