w("backend/schema.sql", "CREATE TABLE t_users (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  col_email VARCHAR(100) NOT NULL DEFAULT '',\n  col_password_hash VARCHAR(256) NOT NULL DEFAULT '',\n  col_name VARCHAR(50) NOT NULL DEFAULT '',\n  col_is_active TINYINT(1) NOT NULL DEFAULT 1,\n  col_can_edit_scheduler TINYINT(1) NOT NULL DEFAULT 0,\n  col_created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id), UNIQUE KEY uniq_email (col_email)\n);\nCREATE TABLE t_schedule_state (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  col_key VARCHAR(50) NOT NULL DEFAULT 'current',\n  col_data LONGTEXT NOT NULL,\n  col_updated_by VARCHAR(100) NOT NULL DEFAULT '',\n  col_updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id), UNIQUE KEY uniq_key (col_key)\n);\n")

w("backend/seed_demo.py", "from app import create_app\nfrom app.extensions import db\nfrom app.models.user import User\napp = create_app()\nwith app.app_context():\n    db.create_all()\n    for u in [\n        {'email':'admin@example.com','name':'Admin','password':'demo123456','can_edit_scheduler':1},\n        {'email':'viewer@example.com','name':'Viewer','password':'demo123456','can_edit_scheduler':0},\n    ]:\n        if not User.query.filter_by(email=u['email']).first():\n            user = User(email=u['email'],name=u['name'],is_active=1,can_edit_scheduler=u['can_edit_scheduler'])\n            user.set_password(u['password'])\n            db.session.add(user)\n    db.session.commit()\n    print('[seed] Done.')\n")

