w("frontend/src/router/index.ts", "import { createRouter, createWebHistory } from 'vue-router'\nimport type { RouteRecordRaw } from 'vue-router'\nimport { getToken } from '@/utils/auth'\nconst routes: RouteRecordRaw[] = [\n  { path: '/login', name: 'Login', component: () => import('@/views/Login/index.vue'), meta: { title: 'Login', public: true } },\n  { path: '/', component: () => import('@/views/Layout/index.vue'), redirect: '/scheduler', children: [\n    { path: '/scheduler', name: 'Scheduler', component: () => import('@/views/Scheduler/index.vue'), meta: { title: 'Shift Scheduler' } },\n    { path: '/users', name: 'Users', component: () => import('@/views/Users/index.vue'), meta: { title: 'User Management' } },\n    { path: '/home', name: 'Home', component: () => import('@/views/Home/index.vue'), meta: { title: 'Home' } }\n  ]}\n]\nconst router = createRouter({ history: createWebHistory(), routes })\nrouter.beforeEach((to, _from, next) => {\n  if (to.meta.public) { next(); return }\n  if (!getToken()) { next({ path: '/login', query: { redirect: to.fullPath } }); return }\n  next()\n})\nexport default router\n")

w("frontend/src/views/Layout/index.vue", '<template>\n  <el-container class="layout-container">\n    <el-aside width="220px">\n      <div class="logo">CS Roster</div>\n      <el-menu :default-active="route.path" router background-color="#304156" text-color="#bfcbd9" active-text-color="#409eff">\n        <el-menu-item index="/scheduler"><el-icon><Calendar /></el-icon><span>Shift Scheduler</span></el-menu-item>\n        <el-menu-item index="/users"><el-icon><User /></el-icon><span>User Management</span></el-menu-item>\n      </el-menu>\n    </el-aside>\n    <el-container>\n      <el-header class="layout-header">\n        <span class="page-title">{{ route.meta.title }}</span>\n        <div class="header-right">\n          <span class="user-name">{{ userName }}</span>\n          <el-button type="danger" text @click="handleLogout">Logout</el-button>\n        </div>\n      </el-header>\n      <el-main><router-view /></el-main>\n    </el-container>\n  </el-container>\n</template>\n<script setup lang="ts">\nimport { ref, onMounted } from \'vue\'\nimport { useRoute, useRouter } from \'vue-router\'\nimport { User, Calendar } from \'@element-plus/icons-vue\'\nimport { getUserInfo } from \'@/api/auth\'\nimport { removeToken } from \'@/utils/auth\'\nconst route = useRoute()\nconst router = useRouter()\nconst userName = ref(\'\')\nonMounted(async () => { try { const u = await getUserInfo(); userName.value = u.name || u.email } catch {} })\nconst handleLogout = () => { removeToken(); router.push(\'/login\') }\n</script>\n<style scoped>\n.layout-container{height:100vh}.logo{height:60px;line-height:60px;text-align:center;font-size:18px;font-weight:bold;color:#fff;background:#263445}.el-aside{background:#304156}.layout-header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e6e6e6;background:#fff}.page-title{font-size:16px;font-weight:500}.header-right{display:flex;align-items:center;gap:12px}.user-name{font-size:14px;color:#606266}\n</style>\n')

w("supervisord.conf", "[supervisord]\nnodaemon=true\nlogfile=/dev/null\nlogfile_maxbytes=0\n[program:nginx]\ncommand=nginx -g \"daemon off;\"\nautostart=true\nautorestart=true\nstdout_logfile=/dev/stdout\nstdout_logfile_maxbytes=0\n[program:init]\ncommand=bash -c \"cd /app/backend && flask db upgrade 2>/dev/null; python seed_demo.py || true\"\ndirectory=/app/backend\nautostart=true\nautorestart=false\nstartsecs=0\npriority=10\n[program:gunicorn]\ncommand=bash -c \"sleep 5; exec gunicorn --bind 127.0.0.1:5000 --workers 2 --timeout 120 run:app\"\ndirectory=/app/backend\nautostart=true\nautorestart=true\npriority=20\nstdout_logfile=/dev/stdout\nstdout_logfile_maxbytes=0\n")

